#!/usr/bin/env python3
import sys
import queue


def solve(N: int, adjacent):
    color = [0] * N
    visited = [False] * N

    visited[0] = True
    
    Q = queue.Queue()
    Q.put(0)
    while not Q.empty():
        u = Q.get()
        for v, w in adjacent[u]:
            if visited[v]:
                continue
            visited[v] = True
            if w == 0:
                color[v] = color[u]
            else:
                color[v] = (color[u] + 1) % 2
            Q.put(v)
    for c in color:
        print(c)


# Generated by 1.1.4 https://github.com/kyuridenamida/atcoder-tools  (tips: You use the default template now. You can remove this line by using your custom template)
def main():
    def iterate_tokens():
        for line in sys.stdin:
            for word in line.split():
                yield word
    tokens = iterate_tokens()
    N = int(next(tokens))  # type: int
    adjacent = [[] for _ in range(N)]
    for i in range(N-1):
        u = int(next(tokens)) - 1
        v = int(next(tokens)) - 1
        w = int(next(tokens)) % 2
        adjacent[u].append((v, w))
        adjacent[v].append((u, w))
    solve(N, adjacent)

if __name__ == '__main__':
    main()
